const families=['literal','long-action','two-actions','three-actions','paraphrase','gift-reference','promise-reference','time-jump','named-promisor','ambiguous-gift','quotation','conditional'] as const;
export interface LongGold { wanted:string[]; noGoldReason?:string; guard:boolean }
export function longWorld(locale:Locale,plotIndex=0,noiseCount=360) {
 const p=plots[plotIndex]!,ru=locale==='ru',names=p[locale],worldId='rp280-'+p.id+'-'+locale;
 const world:WorldProfile={id:worldId,name:ru?'История '+p.id:'Story '+p.id,description:ru?'Вымышленная история взрослых жителей.':'A fictional story about adult residents.',color:'#526879',contextBudget:16000,relevanceThreshold:6,createdAt:1,updatedAt:1};
 const entities:SceneEntity[]=names.slice(0,3).map((name,i)=>({id:worldId+'-person-'+i,worldId,kind:'character',name,description:'',aliases:[],memberIds:[],createdAt:1,updatedAt:1}));
 const a=ru?p.aRu:p.aEn,b=ru?p.bRu:p.bEn,c=ru?p.cRu:p.cEn;
 const facts:StoryFact[]=[],ids:string[]=[],speakers:number[]=[];
 const add=(id:string,body:string,owner:number,extra:Partial<StoryFact>={})=>{const text=ru?`${names[owner]} ${owner===1?'сказал':'сказала'}: «${body}»`:`${names[owner]} said: “${body}”`;ids.push(id);speakers.push(owner);facts.push({kind:'event',text,quote:text,...extra});};
 const old=ru?`${names[3]}: место возврата — прежняя стойка.`:`The ${names[3]}: return location is the old desk.`;
 add('old-location',old,0,{claim:{key:worldId+'-location',value:old,scope:'state',lifetime:'persistent'}});
 a.forEach((body,i)=>add('a'+i,body,0,i===0?{kind:'promise',task:{key:worldId+'-return',title:body,status:'open'}}:i===2?{claim:{key:worldId+'-location',value:body,scope:'state',lifetime:'persistent'}}:i===3?{task:{key:worldId+'-preparation',title:body,status:'completed'}}:{}));
 const noise=(start:number,end:number)=>{for(let i=start;i<end;i++){
   const place=ru?['на набережной','у хлебной лавки','в саду','на площади','возле фонтана'][i%5]:['on the promenade','at the bakery','in the garden','in the square','by the fountain'][i%5];
   const activity=ru?['обсудили погоду','посчитали облака','слушали уличного музыканта','выбирали чай','рассматривали вывески'][Math.floor(i/5)%5]:['discussed the weather','counted clouds','listened to a street musician','chose tea','looked at shop signs'][Math.floor(i/5)%5];
   add('later-'+i,ru?`День ${Math.floor(i/8)+2}, сцена ${i+1}: ${place} ${activity}; новых обязательств не возникло.`:`Day ${Math.floor(i/8)+2}, scene ${i+1}: ${place} we ${activity}; no new commitments arose.`,i%3);
 }};
 noise(0,Math.floor(noiseCount/2));
 b.forEach((body,i)=>add('b'+i,body,1,i===1?{kind:'promise',task:{key:worldId+'-replacement',title:body,status:'open'}}:i===2?{task:{key:worldId+'-delivery',title:body,status:'cancelled'}}:{}));
 noise(Math.floor(noiseCount/2),Math.floor(noiseCount*3/4));
 c.forEach((body,i)=>add('c'+i,body,2,i===1?{task:{key:worldId+'-inspection',title:body,status:'completed'}}:i===2?{kind:'belief'}:{}));
 noise(Math.floor(noiseCount*3/4),noiseCount);
 add('anchor',ru?p.anchorRu:p.anchorEn,0);
 const sources=facts.map((_,i)=>worldId+'-source-'+i);
 const seeds=facts.map((fact,i)=>{const owner=entities[speakers[i]!]!;return roleSeed(fact,{version:1,sourceRevisionId:sources[i]!,quote:fact.quote,roles:{speaker:{id:owner.id,name:owner.name},...(fact.kind==='promise'?{promisor:{id:owner.id,name:owner.name}}:{}),...(fact.kind==='belief'?{believer:{id:owner.id,name:owner.name}}:{})}});});
 const input:GameContextInput={draft:'',recentMessages:[facts.at(-1)!.text],entries:[],books:[],entities,worlds:[world],activeBookId:null,scene:{worldId,bookId:null,focusIds:[]},settings:{contextBudget:16000,relevanceThreshold:6},story:{world,chat:worldId+'-chat',branch:worldId+'-branch',facts,sheetsEnabled:false,roleSeeds:seeds,episodeSources:sources}};
 return {input,ids,sources,speakers,plot:p,locale,noiseCount};
}
export function longScenarios(){
 const rows=(['ru','en'] as const).flatMap(locale=>plots.flatMap((_,pi)=>families.map((family,fi)=>{
   const c=longWorld(locale,pi),gold:LongGold={wanted:fi===2?['a0','a1','a2','a3','b0','b1','b2','anchor']:fi===3?['a0','a1','a2','a3','b0','b1','b2','c0','c1','c2','anchor']:fi===8?['b1']:fi<10?['a0','a1','a2','a3','anchor']:[],guard:fi===5||fi===6||fi===9};
   c.input.draft=(locale==='ru'?c.plot.draftsRu:c.plot.draftsEn)[fi]!;
   if(fi===9){c.input.recentMessages=[c.input.recentMessages[0]+(locale==='ru'?` Другой подарок — ${c.plot.ru[4]}.`:` Another gift is the ${c.plot.en[4]}.`)];gold.wanted=[];gold.noGoldReason='Two explicit gifts: owner/object is ambiguous; require guard and exact evidence, not an invented resolution.';}
   if(fi>=10)gold.noGoldReason='Quoted or conditional intent is not an executed action; only evidence/integrity is scored.';
   return {...c,id:`${locale}:${c.plot.id}:${family}`,family,gold};
 })));
 const scale=(['ru','en'] as const).flatMap(locale=>[250,1000,5000].map(size=>{const c=longWorld(locale,0,size);c.input.draft=(locale==='ru'?c.plot.draftsRu:c.plot.draftsEn)[2];return {...c,id:`${locale}:scale:${size}`,family:'scale',gold:{wanted:['a0','a1','a2','a3','b0','b1','b2','anchor'],guard:false} as LongGold};}));
 return [...rows,...scale];
}
